import { test, expect } from '@playwright/test';

test.describe('Login Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should show error when both fields are empty', async ({ page }) => {
    await page.getByRole('button', { name: /login/i }).click();
    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toHaveText(/username is required/i);
  });

  test('should show error when only username is entered', async ({ page }) => {
    await page.getByLabel('Username').fill('standard_user');
    await page.getByRole('button', { name: /login/i }).click();
    const errorContainer = page.getByTestId('error');
    await expect(errorContainer).toBeVisible();
    await expect(errorContainer).toHaveText(/password is required/i);
  });
});
